1	/**
2	 * 会话级切店（右上角头像 → 切换 →「切换店铺」弹窗）
3	 * 对齐 temu-plugin content.js，多 mall 共用账号时必须用此方式，不能用「来源店铺」筛选。
4	 */
5	import { log } from './logger.js';
6	
7	// 注意：经 page.evaluate → eval(helpers) 注入。必须用 function/var，不能用 const/let
8	// （const/let 不泄漏到 evaluate 外层；切店回调里直接调 realClick/sleep/visible 会挂）。
9	const SWITCH_HELPERS = `
10	  function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
11	  function visible(el) {
12	    if (!el) return false;
13	    const r = el.getBoundingClientRect();
14	    return r.width > 0 && r.height > 0;
15	  }
16	  function textEls(re, maxLen = 40) {
17	    return [...document.querySelectorAll('*')].filter((e) => {
18	      const t = (e.textContent || '').trim();
19	      return re.test(t) && t.length <= maxLen;
20	    });
21	  }
22	  function clickableAncestor(el) {
23	    let p = el;
24	    for (let i = 0; i < 6 && p; i++, p = p.parentElement) {
25	      if (p.tagName === 'BUTTON' || p.getAttribute('role') === 'button') return p;
26	    }
27	    return el;
28	  }
29	  function realClick(el) {
30	    if (!el) return;
31	    const opts = { bubbles: true, cancelable: true, view: window };
32	    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
33	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
34	      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
35	    }
36	    try { el.click(); } catch (e) {}
37	  }
38	  async function waitFor(fn, timeout = 8000, step = 300) {
39	    const t0 = Date.now();
40	    while (Date.now() - t0 < timeout) {
41	      let v = null;
42	      try { v = fn(); } catch (e) { v = null; }
43	      if (v) return v;
44	      await sleep(step);
45	    }
46	    return null;
47	  }
48	  function innermost(els) {
49	    return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null;
50	  }
51	  function findStoreNameEl() {
52	    const W = window.innerWidth;
53	    let best = null;
54	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
55	      const t = (el.textContent || '').trim();
56	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
57	      if (t.length < 2 || t.length > 30) continue;
58	      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
59	      if (/^[A-Z0-9]+$/.test(t)) continue;
60	      if (el.children.length > 2) continue;
61	      const r = el.getBoundingClientRect();
62	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
63	      if (r.left < W * 0.5) continue;
64	      if (!best || r.left > best.left) best = { el, left: r.left };
65	    }
66	    return best ? best.el : null;
67	  }
68	  function readStoreName() {
69	    const el = findStoreNameEl();
70	    return el ? (el.textContent || '').trim() : null;
71	  }
72	  function modalOpen() {
73	    return textEls(/切换店铺|您的账户存在/, 40).length > 0;
74	  }
75	  // 对齐插件：点顶栏店名/箭头 → 下拉「切换」→ 「切换店铺」弹窗
76	  async function openStoreModal() {
77	    if (modalOpen()) return true;
78	    const nameEl = findStoreNameEl();
79	    if (nameEl) {
80	      const r = nameEl.getBoundingClientRect();
81	      realClick(clickableAncestor(nameEl));
82	      const arrow = document.elementFromPoint(
83	        Math.min(window.innerWidth - 3, r.right + 14),
84	        r.top + r.height / 2,
85	      );
86	      if (arrow && arrow !== nameEl) realClick(arrow);
87	    } else {
88	      // 读不到店名时兜底点右上角头像区
89	      const av = [...document.querySelectorAll('img,div,span')].find((e) => {
90	        const r = e.getBoundingClientRect();
91	        return r.top >= 0 && r.top < 80 && r.left > window.innerWidth * 0.85 && r.width > 20 && r.height > 20;
92	      });
93	      if (av) realClick(av);
94	    }
95	    const sw = await waitFor(() => {
96	      const cands = textEls(/^切换$/, 6).filter(visible);
97	      return cands.length ? clickableAncestor(cands[cands.length - 1]) : null;
98	    }, 3500, 200);
99	    if (sw) realClick(sw);
100	    return !!(await waitFor(() => (modalOpen() ? true : null), 4500, 200));
101	  }
102	`;
103	
104	export async function readCurrentStoreName(page) {
105	  return page.evaluate((helpers) => {
106	    // eslint-disable-next-line no-eval
107	    eval(helpers);
108	    return readStoreName();
109	  }, SWITCH_HELPERS);
110	}
111	
112	/**
113	 * 切换到目标店铺（会话级）。已是当前店则 ok。
114	 * @returns {Promise<{ok:boolean,msg:string}>}
115	 */
116	export async function switchSessionStore(page, target) {
117	  const cur = await readCurrentStoreName(page);
118	  if (cur && cur === target) {
119	    log.info(`已是当前店：${target}`);
120	    return { ok: true, msg: 'already' };
121	  }
122	  log.info(`会话切店 → ${target}（当前=${cur || '未知'}）`);
123	  // Playwright page.evaluate 只接受 1 个参数，多个值必须包成对象
124	  const result = await page.evaluate(async ({ helpers, targetName }) => {
125	    // eslint-disable-next-line no-eval
126	    eval(helpers);
127	    if (!(await openStoreModal())) return { ok: false, msg: '打不开切换店铺弹窗' };
128	    await sleep(400);
129	    const esc = String(targetName).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
130	    // 对齐插件：找含店名且含「切换」的最短节点作行容器
131	    const rows = textEls(new RegExp(esc), 120).filter((e) => /切换/.test(e.textContent || ''));
132	    const row = innermost(rows);
133	    if (!row) return { ok: false, msg: '弹窗里没找到店铺 ' + targetName };
134	    let btn = [...row.querySelectorAll('button,[role=button]')].find(
135	      (b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true',
136	    );
137	    if (!btn) {
138	      const allSwitch = textEls(/^切换$/, 6)
139	        .map(clickableAncestor)
140	        .filter((b) => b && !b.disabled && visible(b));
141	      btn =
142	        allSwitch.find(
143	          (b) =>
144	            row.contains(b) ||
145	            (b.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_CONTAINED_BY),
146	        ) || allSwitch[allSwitch.length - 1];
147	    }
148	    if (!btn) return { ok: false, msg: '没找到可点的切换按钮（可能已是当前店）' };
149	    realClick(btn);
150	    return { ok: true, msg: 'clicked' };
151	  }, { helpers: SWITCH_HELPERS, targetName: target });
152	
153	  if (!result.ok) {
154	    log.warn(`切店失败：${result.msg}`);
155	    await page.keyboard.press('Escape').catch(() => {});
156	    return result;
157	  }
158	  // 等顶栏店名变化或导航完成
159	  await page.waitForTimeout(2500);
160	  const deadline = Date.now() + 25000;
161	  while (Date.now() < deadline) {
162	    const name = await readCurrentStoreName(page);
163	    if (name === target) {
164	      log.info(`切店成功：${target}`);
165	      return { ok: true, msg: 'switched' };
166	    }
167	    await page.waitForTimeout(800);
168	  }
169	  const after = await readCurrentStoreName(page);
170	  if (after === target) return { ok: true, msg: 'switched-late' };
171	  log.warn(`切店超时，当前显示=${after || '未知'}，目标=${target}`);
172	  return { ok: false, msg: `timeout current=${after}` };
173	}
