1	/**
2	 * 全量一轮：插件全部能力，不依赖 Chrome 扩展
3	 *
4	 *  1) 赛狐 OpenAPI → 下架/上架点名（selectStatus 离开/进入 12）
5	 *  2) Playwright  → 多店会话切店 + 待关注/近期下降点名 + 在售数字
6	 *  3) 飞书汇总
7	 */
8	import { existsSync } from 'node:fs';
9	import { resolve } from 'node:path';
10	import { launchBrowser, isLoggedIn } from './browser.js';
11	import { closePopups } from './popups.js';
12	import { scanStore, attachCountStatusCapture } from './monitor.js';
13	import { loadState, saveState, diffStore, mergeSnapshot } from './state.js';
14	import { sendFeishu } from './feishu.js';
15	import { switchSessionStore, readCurrentStoreName } from './sessionStores.js';
16	import { loadSellfoxConfig, sellfoxConfigReady } from './sellfox/config.js';
17	import { runSellfoxOnce } from './sellfox/monitor.js';
18	import { ROOT } from './config.js';
19	import { log } from './logger.js';
20	
21	function resolveStoreList(cfg) {
22	  // 优先 config.storeList；否则用赛狐配置店名
23	  if (Array.isArray(cfg.storeList) && cfg.storeList.length) {
24	    return cfg.storeList.map(String);
25	  }
26	  try {
27	    const sf = loadSellfoxConfig();
28	    const names = (sf.stores || [])
29	      .filter((s) => s.enabled !== false)
30	      .map((s) => s.name)
31	      .filter(Boolean);
32	    if (names.length) return names;
33	  } catch {
34	    /* ignore */
35	  }
36	  return [];
37	}
38	
39	function sellfoxAvailable() {
40	  const p = resolve(ROOT, 'sellfox.config.json');
41	  if (!existsSync(p) && !process.env.SELLFOX_CLIENT_ID) return false;
42	  try {
43	    const c = loadSellfoxConfig();
44	    return sellfoxConfigReady(c).ok;
45	  } catch {
46	    return false;
47	  }
48	}
49	
50	/**
51	 * @param {object} cfg loadConfig()
52	 * @param {{ skipSellfox?: boolean, skipBrowser?: boolean, dryRun?: boolean }} [opts]
53	 */
54	export async function runFullOnce(cfg, opts = {}) {
55	  const report = {
56	    sellfox: null,
57	    browser: null,
58	    events: [],
59	  };
60	  const allLines = [];
61	
62	  // ---------- 1) 赛狐上下架 ----------
63	  const wantSellfox =
64	    !opts.skipSellfox &&
65	    sellfoxAvailable() &&
66	    (cfg.alerts?.delist !== false || cfg.alerts?.onshelf !== false);
67	  if (wantSellfox) {
68	    try {
69	      log.info('=== [1/2] 赛狐上下架监测 ===');
70	      const sfCfg = loadSellfoxConfig();
71	      // 主 config 若显式关了某类告警，覆盖到赛狐配置
72	      if (cfg.alerts?.delist === false) sfCfg.alerts.delist = false;
73	      if (cfg.alerts?.onshelf === false) sfCfg.alerts.onshelf = false;
74	      // 飞书：dry 时不发；正式时 sellfox 模块自己发，避免 double——这里 dryRun 控制
75	      const r = await runSellfoxOnce(sfCfg, { dryRun: !!opts.dryRun });
76	      report.sellfox = r;
77	      // 已在 runSellfoxOnce 内发飞书；汇总记一条
78	      for (const s of r.summary || []) {
79	        if (s.events?.includes('delist')) {
80	          report.events.push({ store: s.store, type: 'delist', via: 'sellfox' });
81	        }
82	        if (s.events?.includes('onshelf')) {
83	          report.events.push({ store: s.store, type: 'onshelf', via: 'sellfox' });
84	        }
85	      }
86	    } catch (e) {
87	      log.error('赛狐上下架失败：', e.message);
88	      report.sellfox = { error: e.message };
89	      const msg = String(e.message || e);
90	      // 白名单类错误：多半是本机 IP 未加白，不刷飞书（避免同事本机 fullRun 误开时刷屏）
91	      const isWhitelist =
92	        /40005|白名单|不在白名单|ip\s*not\s*in|not\s*in\s*whitelist/i.test(msg);
93	      if (!opts.dryRun && !isWhitelist) {
94	        await sendFeishu(cfg, {
95	          title: '⚠️ 赛狐上下架监测失败',
96	          template: 'orange',
97	          lines: [
98	            msg,
99	            isWhitelist ? '_提示：赛狐请放到固定 IP 服务器跑，本机只跑流量_' : '',
100	            `_时间：${new Date().toLocaleString('zh-CN')}_`,
101	          ].filter(Boolean),
102	        }).catch(() => {});
103	      } else if (isWhitelist) {
104	        log.warn('赛狐 IP 不在白名单 — 已跳过飞书失败告警。上下架请用服务器 sellfox 服务。');
105	      }
106	    }
107	  } else {
108	    log.info('跳过赛狐上下架（未配置或 skipSellfox / 告警全关）');
109	  }
110	
111	  // ---------- 2) 浏览器：流量 + 在售数字 ----------
112	  if (opts.skipBrowser) {
113	    log.info('跳过浏览器扫描');
114	    return report;
115	  }
116	
117	  log.info('=== [2/2] 浏览器流量/在售监测 ===');
118	  const { context, page } = await launchBrowser(cfg);
119	  const countCapture = attachCountStatusCapture(page);
120	  try {
121	    if (!(await isLoggedIn(page, cfg))) {
122	      const err = new Error('未登录。请先运行 `npm run login`。');
123	      err.code = 'NOT_LOGGED_IN';
124	      throw err;
125	    }
126	    await closePopups(page);
127	
128	    let stores = resolveStoreList(cfg);
129	    if (!stores.length) {
130	      const cur = await readCurrentStoreName(page);
131	      stores = [cur || '(当前店铺)'];
132	      log.info('未配置 storeList，监测当前店：', stores[0]);
133	    } else {
134	      log.info('店铺清单：', stores.join(', '));
135	    }
136	
137	    const state = loadState();
138	    state.stores = state.stores || {};
139	    const browserEvents = [];
