async function ensureTop(page) {
  await page.evaluate(() => {
    try {
      window.scrollTo(0, 0);
      document.documentElement.scrollTop = 0;
      document.body.scrollTop = 0;
    } catch {}
  }).catch(() => {});
  await page.waitForTimeout(200).catch(() => {});
}

