      log.error('本轮监测失败：', e.message);
      if (e.code === 'NOT_LOGGED_IN') {
        loginFailStreak++;
        await maybeAlertLoginExpiry(loginFailStreak, loginAlertedAt).then((sent) => {
          if (sent) loginAlertedAt = loginFailStreak;
