/**
 * 轻量探测当前页会话状态（不导航）。用于区分：
 *  - browser_gone：进程/页被关（本机双开抢锁、杀 chrome）
 *  - session_kicked：还在登录页/登录表单（过期，或同账号其它浏览器登录互踢）
 *  - ok / unknown
 * @returns {Promise<{kind:string, url?:string, detail?:string}>}
 */
export async function peekSession(page) {
  try {
    if (!page || page.isClosed()) {
      return { kind: 'browser_gone', detail: 'page.isClosed' };
    }
    let url = '';
    try { url = page.url(); } catch {
      return { kind: 'browser_gone', detail: 'page.url failed' };
    }
    if (/login|signin|authentication|account\/login/i.test(url)) {
      return { kind: 'session_kicked', url, detail: 'url looks like login' };
    }
    const loginForm = await page
      .locator('input[type="password"], text=账号登录, text=扫码登录')
      .first()
      .isVisible({ timeout: 800 })
      .catch(() => false);
    if (loginForm) {
      return { kind: 'session_kicked', url, detail: 'login form visible' };
    }
    const goodsHint = await page
      .getByText(/商品列表|在售中|全部\s*\d+/)
      .first()
      .isVisible({ timeout: 800 })
      .catch(() => false);
    if (goodsHint) return { kind: 'ok', url };
    return { kind: 'unknown', url };
  } catch (e) {
    const m = String(e?.message || e);
    if (/has been closed|Target closed|Browser closed/i.test(m)) {
      return { kind: 'browser_gone', detail: m.split('\n')[0] };
    }
    return { kind: 'unknown', detail: m.split('\n')[0] };
  }
}

/** 会话失效时的统一说明（日志 / Error.message 复用） */
export const SESSION_KICKED_HINT =
  '监测登录态失效（页面在登录页或出现登录表单）。可能原因：' +
  '①.userdata 过期未重登；' +
  '②同一 Temu 账号在日常 Chrome 重新登录，服务端踢掉监测会话；' +
  '③风控/异地。' +
  '处理：先停常驻 → npm run login（或启动器「登录 Temu」）→ 再开常驻。' +
  '若经常与人工操作撞车，可人工大改时先停监测。';

/**
 * 判断当前是否已登录：访问商品列表页，若被重定向到登录页或出现登录表单则未登录。
 * 失败时会打分类日志（过期/互踢 vs 网关打不开）。
 */
export async function isLoggedIn(page, cfg) {
  const navOk = await gotoWithRetry(page, cfg.goodsListUrl, cfg);
  if (!navOk) log.warn('多次尝试后仍无法打开商品列表页（网关重置或网络问题）。');
  // commit 后 DOM 尚未渲染，先等关键内容或登录表单出现
  const ok = await waitForGoodsList(page, { timeout: cfg.navTimeoutMs });
  const url = page.url();
  // 登录页通常包含 login 关键字，或出现「登录」「密码」输入
  if (/login|signin|authentication|account/i.test(url)) {
    log.warn(`未登录判定：URL 像登录页 → ${url}`);
    log.warn(SESSION_KICKED_HINT);
    return false;
  }
  const loginForm = await page
    .locator('input[type="password"], text=账号登录, text=扫码登录')
    .first()
    .isVisible()
    .catch(() => false);
  if (loginForm) {
    log.warn(`未登录判定：可见登录表单（url=${url}）`);
    log.warn(SESSION_KICKED_HINT);
    return false;
  }
  // 已登录时商品列表页应能看到「商品列表」或状态标签
  if (!ok) {
    log.warn(`未登录判定：商品列表关键文案未出现（url=${url}，navOk=${navOk}）`);
  }
  return ok;
}

