      if (got) {
        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
        if (os && os.msg) log.warn('scanOnSale aborted: store=' + name + ' ' + os.msg);
        if (os && Array.isArray(os.items)) { const d = await diffOnSale(name, os.items, os.onSaleTabCount, os.store); if (d) { log.warn('Cycle delisted: store=' + name + ' count=' + d); cycleLog.push('  ↳下架' + d + '个'); } }
      }
    }
    // 切回原店
    if (original) {
      const since = Date.now();
      await sendTabRetry(tab.id, { cmd: 'switchTo', target: original }, 5);
      const gotBack = await waitForStoreCapture(original, since, 25000);
      if (gotBack) {
        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
        if (os && os.msg) log.warn('scanOnSale aborted: store=' + original + ' ' + os.msg);
        if (os && Array.isArray(os.items)) { const d = await diffOnSale(original, os.items, os.onSaleTabCount, os.store); if (d) cycleLog.push('  ↳' + original + '下架' + d + '个'); }
      }
      cycleLog.push('已切回 ' + original);
    }

