1	/**
2	 * 赛狐 Temu 在售集合 diff → 下架 / 上架
3	 * 在售定义：selectStatus === "12"（已加入站点）
4	 */
5	import { SELECT_STATUS } from './products.js';
6	
7	/**
8	 * @param {object|null} prevSnap { onSaleMap, statusCounts, ts }
9	 * @param {{ onSaleMap: object, statusCounts?: object }} curr
10	 */
11	export function diffOnSale(prevSnap, curr) {
12	  const prevMap = (prevSnap && prevSnap.onSaleMap) || null;
13	  const currMap = curr.onSaleMap || {};
14	  const currIds = Object.keys(currMap);
15	  const events = [];
16	  let skipUpdate = false;
17	
18	  if (prevMap) {
19	    const prevN = Object.keys(prevMap).length;
20	    const currN = currIds.length;
21	    // 防残缺：在售骤降过半且基准≥5 → 跳过（接口窗口漏数，避免误报下架/上架）
22	    if (prevN >= 5 && currN < Math.floor(prevN * 0.5)) {
23	      skipUpdate = true;
24	      events.push({
25	        type: 'scan_incomplete',
26	        severity: 'warn',
27	        message: `在售疑似不全：基准 ${prevN} → 本轮 ${currN}，跳过上下架判定`,
28	      });
29	    }
30	  }
31	
32	  let delisted = [];
33	  let listed = [];
34	  if (prevMap && !skipUpdate) {
35	    const prevIds = Object.keys(prevMap);
36	    delisted = prevIds.filter((id) => !(id in currMap));
37	    listed = currIds.filter((id) => !(id in prevMap));
38	
39	    if (delisted.length) {
40	      events.push({
41	        type: 'delist',
42	        severity: 'alert',
43	        items: delisted.map((id) => ({
44	          skcId: id,
45	          parentId: prevMap[id]?.parentId || '',
46	          name: prevMap[id]?.name || '',
47	          selectStatus: prevMap[id]?.selectStatus || SELECT_STATUS.ON_SALE,
48	        })),
49	        from: prevIds.length,
50	        to: currIds.length,
51	      });
52	    }
53	    if (listed.length) {
54	      events.push({
55	        type: 'onshelf',
56	        severity: 'alert',
57	        items: listed.map((id) => ({
58	          skcId: id,
59	          parentId: currMap[id]?.parentId || '',
60	          name: currMap[id]?.name || '',
61	          selectStatus: currMap[id]?.selectStatus || SELECT_STATUS.ON_SALE,
62	        })),
63	        from: prevIds.length,
64	        to: currIds.length,
65	      });
66	    }
67	  }
68	
69	  const isFirst = !prevMap;
70	  const nextSnap = {
71	    onSaleMap: skipUpdate && prevMap ? prevMap : currMap,
72	    statusCounts: curr.statusCounts || {},
73	    onSaleCount: skipUpdate && prevMap ? Object.keys(prevMap).length : currIds.length,
74	    ts: Date.now(),
75	  };
76	
77	  return {
78	    events,
79	    nextSnap,
80	    isFirst,
81	    skipUpdate,
82	    delistedCount: delisted.length,
83	    listedCount: listed.length,
84	  };
85	}
86	
87	export function editLink(editBaseUrl, parentIdOrProductId) {
88	  const base = String(editBaseUrl || 'https://agentseller.temu.com').replace(/\/$/, '');
89	  // 后台编辑页参数多为 productId；赛狐 parentId 实测常等于商品父 ID，可点
90	  return `${base}/goods/edit?from=productList&productId=${parentIdOrProductId}`;
91	}
92	
93	function itemBullet(it, editBaseUrl) {
94	  const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 36);
95	  const pid = it.parentId || it.skcId;
96	  return `• [${nm}](${editLink(editBaseUrl, pid)})  SKC ${it.skcId || '-'}`;
97	}
98	
99	/**
100	 * 把 delist / onshelf 告警拼成飞书 lark_md 行
101	 * @param {string} storeName
102	 * @param {Array} events
103	 * @param {{ editBaseUrl?: string }} [opts]
104	 */
105	export function formatChangeLines(storeName, events, { editBaseUrl } = {}) {
106	  const lines = [`**🏬 ${storeName}**（赛狐 OpenAPI）`];
107	  let any = false;
108	  for (const ev of events) {
109	    if (ev.severity !== 'alert') continue;
110	    if (ev.type === 'delist' && ev.items?.length) {
111	      any = true;
112	      lines.push(
113	        `📉 在售商品**下架** ${ev.items.length} 个（在售 ${ev.from} → ${ev.to}，离开 selectStatus=12）：`,
114	      );
115	      for (const it of ev.items.slice(0, 40)) lines.push(itemBullet(it, editBaseUrl));
116	      if (ev.items.length > 40) lines.push(`_…另有 ${ev.items.length - 40} 个未列出_`);
117	    }
118	    if (ev.type === 'onshelf' && ev.items?.length) {
119	      any = true;
120	      lines.push(
121	        `📈 在售商品**上架** ${ev.items.length} 个（在售 ${ev.from} → ${ev.to}，进入 selectStatus=12）：`,
122	      );
123	      for (const it of ev.items.slice(0, 40)) lines.push(itemBullet(it, editBaseUrl));
124	      if (ev.items.length > 40) lines.push(`_…另有 ${ev.items.length - 40} 个未列出_`);
125	    }
126	  }
127	  if (!any) lines.push('_本轮无上下架_');
128	  lines.push('', `_检查时间：${new Date().toLocaleString('zh-CN')}_`);
129	  return lines;
130	}
131	
132	/** @deprecated 用 formatChangeLines；保留别名避免外部引用断裂 */
133	export function formatDelistLines(storeName, events, opts) {
134	  return formatChangeLines(storeName, events, opts);
135	}
136	
137	/**
138	 * 飞书卡片颜色：仅下架 red；仅上架 green；混合 orange
139	 * @param {Array} events
140	 */
141	export function alertTemplate(events) {
142	  const types = new Set(
143	    (events || []).filter((e) => e.severity === 'alert').map((e) => e.type),
144	  );
145	  const hasD = types.has('delist');
146	  const hasO = types.has('onshelf');
147	  if (hasD && hasO) return 'orange';
148	  if (hasO) return 'green';
149	  return 'red';
150	}
151	
152	export function alertTitle(events) {
153	  const types = new Set(
154	    (events || []).filter((e) => e.severity === 'alert').map((e) => e.type),
155	  );
156	  const hasD = types.has('delist');
157	  const hasO = types.has('onshelf');
158	  if (hasD && hasO) return '🔔 Temu 在售变动（赛狐）';
159	  if (hasO) return '🔔 Temu 上架监测（赛狐）';
160	  return '🔔 Temu 下架监测（赛狐）';
161	}
162

