1	/**
2	 * 赛狐 Temu 下架监测一轮
3	 */
4	import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
5	import { dirname } from 'node:path';
6	import { createSellfoxClient } from './client.js';
7	import { fetchAllCrossParents, groupByShop, SELECT_STATUS } from './products.js';
8	import { diffOnSale, formatChangeLines, alertTemplate, alertTitle } from './diff.js';
9	import { shopNameMap } from './config.js';
10	import { sendFeishu } from '../feishu.js';
11	import { log } from '../logger.js';
12	
13	function loadState(path) {
14	  try {
15	    if (!existsSync(path)) return { stores: {} };
16	    return JSON.parse(readFileSync(path, 'utf8'));
17	  } catch {
18	    return { stores: {} };
19	  }
20	}
21	
22	function saveState(path, state) {
23	  mkdirSync(dirname(path), { recursive: true });
24	  writeFileSync(path, JSON.stringify(state, null, 2), 'utf8');
25	}
26	
27	/**
28	 * @param {object} cfg loadSellfoxConfig()
29	 * @param {{ dryRun?: boolean }} [opts]
30	 */
31	export async function runSellfoxOnce(cfg, opts = {}) {
32	  const shops = (cfg.stores || []).filter((s) => s.enabled !== false && s.shopId);
33	  if (!cfg.clientId || !cfg.clientSecret) throw new Error('缺少 clientId/clientSecret');
34	  if (!shops.length) throw new Error('没有店铺');
35	
36	  const client = createSellfoxClient({
37	    baseUrl: cfg.baseUrl,
38	    clientId: cfg.clientId,
39	    clientSecret: cfg.clientSecret,
40	    debug: cfg.debug,
41	  });
42	
43	  const shopIds = shops.map((s) => s.shopId);
44	  const names = shopNameMap(cfg);
45	
46	  log.info(`Sellfox 拉取 Temu 跨境父体：shops=${shopIds.join(',')} dateType=${cfg.dateType} lookback=${cfg.lookbackDays}d`);
47	  const { items, meta } = await fetchAllCrossParents(client, {
48	    shopIds,
49	    pageSize: cfg.pageSize,
50	    maxPagesPerWindow: cfg.maxPagesPerWindow,
51	    dateType: cfg.dateType,
52	    lookbackDays: cfg.lookbackDays,
53	  });
54	  log.info(`拉取完成 unique=${meta.unique} windows=${meta.windows}`);
55	
56	  const grouped = groupByShop(items, names);
57	  const state = loadState(cfg.stateFile);
58	  if (!state.stores) state.stores = {};
59	
60	  const summary = [];
61	
62	  for (const shop of shops) {
63	    const sid = shop.shopId;
64	    const name = names[sid] || shop.name || sid;
65	    const g = grouped[sid] || {
66	      shopId: sid,
67	      shopName: name,
68	      onSaleMap: {},
69	      statusCounts: {},
70	    };
71	    const onSaleN = Object.keys(g.onSaleMap).length;
72	    log.info(
73	      `${name}(${sid}) 在售(12)=${onSaleN} 状态分布=${JSON.stringify(g.statusCounts || {})}`,
74	    );
75	
76	    const prev = state.stores[sid]?.snapshot || null;
77	    const { events, nextSnap, isFirst, skipUpdate } = diffOnSale(prev, {
78	      onSaleMap: g.onSaleMap,
79	      statusCounts: g.statusCounts,
80	    });
81	
82	    if (isFirst) {
83	      log.info(`${name} 首轮：建立在售基准 ${onSaleN}，不告警`);
84	    } else if (skipUpdate) {
85	      log.warn(`${name} 跳过上下架更新（扫描疑似不全）`);
86	    }
87	
88	    // 按配置过滤：delist / onshelf 可分别关闭（默认都开）
89	    const alertEvents = events.filter((e) => {
90	      if (e.severity !== 'alert') return false;
91	      if (e.type === 'delist') return cfg.alerts?.delist !== false;
92	      if (e.type === 'onshelf') return cfg.alerts?.onshelf !== false;
93	      return false;
94	    });
95	
96	    if (alertEvents.length && !opts.dryRun) {
97	      const lines = formatChangeLines(name, alertEvents, { editBaseUrl: cfg.editBaseUrl });
98	      await sendFeishu(
99	        { feishuWebhooks: cfg.feishuWebhooks, feishuSecret: cfg.feishuSecret },
100	        {
101	          title: alertTitle(alertEvents),
102	          template: alertTemplate(alertEvents),
103	          lines,
104	        },
105	      );
106	      const nDelist = alertEvents
107	        .filter((e) => e.type === 'delist')
108	        .reduce((n, e) => n + (e.items?.length || 0), 0);
109	      const nShelf = alertEvents
110	        .filter((e) => e.type === 'onshelf')
111	        .reduce((n, e) => n + (e.items?.length || 0), 0);
112	      const parts = [];
113	      if (nDelist) parts.push(`下架 ${nDelist}`);
114	      if (nShelf) parts.push(`上架 ${nShelf}`);
115	      log.info(`${name} 已告警${parts.join('、')} 个`);
116	    } else if (alertEvents.length && opts.dryRun) {
117	      log.info(
118	        `${name} dryRun:`,
119	        formatChangeLines(name, alertEvents, { editBaseUrl: cfg.editBaseUrl }),
120	      );
121	    } else if (!isFirst && !skipUpdate) {
122	      log.info(`${name} 本轮无上下架`);
123	    }
124	
125	    state.stores[sid] = {
