1	import { appendFileSync, mkdirSync } from 'node:fs';
2	import { resolve } from 'node:path';
3	import { ROOT } from './config.js';
4	
5	// 双写：data/monitor.log（历史路径，兼容旧脚本）+ logs/monitor-YYYYMMDD.log（按日、好找）
6	const DATA_DIR = resolve(ROOT, 'data');
7	const LOGS_DIR = resolve(ROOT, 'logs');
8	try { mkdirSync(DATA_DIR, { recursive: true }); } catch {}
9	try { mkdirSync(LOGS_DIR, { recursive: true }); } catch {}
10	
11	const LEGACY_LOG = resolve(DATA_DIR, 'monitor.log');
12	
13	function dayStamp() {
14	  // 本地日历日（不用 UTC），避免按日文件跨日错位
15	  const d = new Date();
16	  const y = d.getFullYear();
17	  const m = String(d.getMonth() + 1).padStart(2, '0');
18	  const day = String(d.getDate()).padStart(2, '0');
19	  return `${y}${m}${day}`;
20	}
21	
22	function dailyLogPath() {
23	  return resolve(LOGS_DIR, `monitor-${dayStamp()}.log`);
24	}
25	
26	let announced = false;
27	
28	function ts() {
29	  // ISO 存盘统一；控制台也用同一格式，排障时好对齐
30	  return new Date().toISOString().replace('T', ' ').slice(0, 19);
31	}
32	
33	function write(level, args) {
34	  const line = `[${ts()}] [${level}] ${args.map(fmt).join(' ')}`;
35	  if (level === 'ERROR') console.error(line);
36	  else console.log(line);
37	  // 文件写失败不能再递归 log.error，吞掉即可
38	  try { appendFileSync(LEGACY_LOG, line + '\n'); } catch {}
39	  try { appendFileSync(dailyLogPath(), line + '\n'); } catch {}
40	}
41	
42	function fmt(a) {
43	  if (typeof a === 'string') return a;
44	  if (a instanceof Error) return a.stack || a.message || String(a);
45	  try { return JSON.stringify(a); } catch { return String(a); }
46	}
47	
48	export const log = {
49	  info: (...a) => write('INFO', a),
50	  warn: (...a) => write('WARN', a),
51	  error: (...a) => write('ERROR', a),
52	  /**
53	   * 进程启动时喊一声落盘路径，避免同事以为「没写日志」。
